using System;
using System.Linq;
using System.Reflection;
using UnityEngine;
namespace BWVR.Editor {
public static class BlockReturnChecks {
 static readonly BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Check(bool ok,string why){if(!ok)throw new Exception(why);}
 public static void Verify(Action<QuestSlice> capture=null){
  Check(Application.isPlaying,"Enter Play mode");var slice=UnityEngine.Object.FindAnyObjectByType<QuestSlice>();var god=slice.GetComponentInChildren<CreatureHybrid>();var site=god.GetComponent<CreatureConstructionLearning>().sites[0];var field=typeof(QuestSlice).GetField("state",F);var original=field.GetValue(slice);var geometry=site.Capture();var recipe=site.Recipe;bool paused=site.Paused,locked=site.Locked;float timeScale=Time.timeScale;Time.timeScale=0;var test=new SliceState{developmentFocus=true,observeWithoutFoodWork=true};test.Hybrid.time=100;
  var hands=(CarryItem[])typeof(QuestSlice).GetField("held",F).GetValue(slice);Check(hands.All(h=>h==null),"Release held objects");var people=slice.GetComponentsInChildren<VillagerExploration>();
  bool Available(){var args=new object[]{null,null};return (bool)typeof(QuestSlice).GetMethod("TryBlockReturn",F).Invoke(slice,args);}
  void NativePlace(ConstructionBlock b,Vector3 p){Check((bool)typeof(QuestSlice).GetMethod("TryGrab",F).Invoke(slice,new object[]{1,b.Item}),"Native grab failed: menu="+slice.MenuOpen+", active="+b.gameObject.activeInHierarchy+", canGrab="+b.Item.CanGrab+", held="+b.Item.held+", hands="+hands.Count(h=>h!=null));Physics.SyncTransforms();typeof(QuestSlice).GetMethod("Release",F).Invoke(slice,new object[]{1,new Ray(site.World(new Vector3(p.x,12,p.z)),Vector3.down)});Check(b.Attached,"Native snap failed");}
  try{
   god.Interrupt("Block return QA");foreach(var p in people){p.ResetTask();p.GetComponent<VillagerSocial>().ResetTask();p.GetComponent<VillagerResourceGathering>().Cancel();p.GetComponent<VillagerBlockPlay>().ResetTask();}field.SetValue(slice,test);slice.SetSanctuaryOpen(false);var palette=slice.GetComponentInChildren<GodToolPalette>();palette.Cancel();palette.Process(new Ray(Camera.main.transform.position,Camera.main.transform.forward),false,true,false,.1f,false);site.Paused=site.Locked=false;site.ResetConstruction();site.Recipe=BuildRecipe.Tower;
   Check(JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(new SliceState())).Valid(),"Empty optional ticket broke save roundtrip");Check(new SliceState().Valid()&&!Available()&&!slice.ReturnLastBlock(),"Legacy or empty recall failed");var b=site.blocks.First(x=>x.Shape==ConstructionShape.Brick);NativePlace(b,new Vector3(-12,0,-12));Check(test.blockReturn!=null&&test.blockReturn.Valid()&&Available(),"Confirmed native placement has no recall");
   string before=JsonUtility.ToJson(test);slice.ShowCreationBook(true);slice.SelectCreationBook(CreationBookSection.Places);int count=CreationBookText.Read(test,CreationBookSection.Places).count;for(int i=0;i<count-2;i++)slice.TurnCreationBook(1);Check(before==JsonUtility.ToJson(test),"Book mutated recall data");Canvas.ForceUpdateCanvases();var body=(UnityEngine.UI.Text)typeof(QuestSlice).GetField("bookBody",F).GetValue(slice);Check(body.preferredHeight<=body.rectTransform.rect.height+1,"Recall instructions overflow");capture?.Invoke(slice);
   test.paused=true;Check(!Available()&&!slice.ReturnLastBlock(),"Paused recall allowed");test.paused=false;site.Locked=true;Check(!Available(),"Locked site allowed");site.Locked=false;site.Visitor=people[0];Check(!Available(),"Occupied structure allowed");site.Visitor=null;test.gatewayProject=new GatewayProject{phase=GatewayPhase.Active};Check(!Available(),"Active project allowed");test.gatewayProject=null;
   var savedPose=b.Body.position;b.Body.position+=Vector3.right;Check(!Available(),"Moved block allowed");b.Body.position=savedPose;b.creatureBuilt=true;Check(!Available(),"Creature block allowed");b.creatureBuilt=false;
   var child=site.blocks.First(x=>x!=b&&x.Shape==ConstructionShape.Brick);Check(site.Drop(child,site.World(b.Body.position+new Vector3(0,b.size.y,0)),site.transform.rotation),"Could not stage dependent piece");Check(child.Connection.connectedBody==b.Body&&!Available()&&!slice.ReturnLastBlock(),"Supporting piece was recalled");site.ReturnLoose(child);Check(Available(),"Leaf remained unavailable");
   var receipt=test.blockReturn.receipt;var log=JsonUtility.ToJson(test.placeContributions);int snaps=site.successfulSnaps;var button=(GameObject)typeof(QuestSlice).GetField("outingGo",F).GetValue(slice);Check(button.activeInHierarchy&&button.GetComponentInChildren<UnityEngine.UI.Text>().text=="Return last block","Book recall button absent");typeof(QuestSlice).GetMethod("BookPointer",F).Invoke(slice,new object[]{1,true,false,button.GetComponent<Collider>(),true});Check(!b.Attached&&test.blockReturn.consumed&&!slice.ReturnLastBlock()&&site.successfulSnaps==snaps&&JsonUtility.ToJson(test.placeContributions)==log,"Recall duplicated/rewrote history or rewards");
   typeof(QuestSlice).GetMethod("Save",F).Invoke(slice,null);typeof(QuestSlice).GetMethod("Load",F).Invoke(slice,null);test=(SliceState)field.GetValue(slice);Check(test.Valid()&&test.blockReturn.consumed&&!Available(),"Native save/load lost consumed ticket");slice.ShowCreationBook(false);slice.SetSanctuaryOpen(false);palette.Process(new Ray(Camera.main.transform.position,Camera.main.transform.forward),false,true,true,.1f,false);test.Hybrid.time+=1;NativePlace(b,new Vector3(-12,0,-12));Check(Available()&&test.blockReturn.receipt>receipt,"Fresh placement did not renew ticket");
   test.placeContributions.Add(0,site.blocks.IndexOf(b),"creature",false,test.Hybrid.time);Check(!Available(),"New owner receipt allowed");test.blockReturn.rotation=new Quaternion(0,0,0,0);Check(!test.Valid(),"Malformed ticket accepted");
   Debug.Log("BWVR_BLOCK_RETURN_PASS: native pickup/snap, pure Book navigation, visible control/pointer activation, pause/lock/occupancy/project/moved/creature/support guards, one-use recall without rewards/history mutation, native save/load, renewed ticket, latest owner and malformed save validation");
  }finally{slice.ShowCreationBook(false);foreach(var p in people)p.ResetTask();if(hands[1]!=null){hands[1].held=false;hands[1]=null;}god.Interrupt("Return QA complete");field.SetValue(slice,original);site.Visitor=null;site.Recipe=recipe;site.Restore(geometry);site.Paused=paused;site.Locked=locked;Time.timeScale=timeScale;}
 }
}
}
